function cleanText(value, fallback = '') {
  if (value === null || value === undefined) return fallback;

  return String(value)
    .replace(/^=/, '')
    .trim();
}

function cleanUpper(value, fallback = '') {
  return cleanText(value, fallback)
    .toUpperCase()
    .trim();
}

const input = $input.first().json || {};

const lockers = Array.isArray(input.lockers) ? input.lockers : [];

const packageSize = cleanUpper(
  input.package_size ||
  $('When called by Agent').first().json.package_size ||
  ''
);

const zipCode = cleanText(
  $('When called by Agent').first().json.zip_code ||
  input.zip_code ||
  ''
);

const sizeRank = {
  SMALL: 1,
  MEDIUM: 2,
  LARGE: 3,
};

function evaluateLocker(locker) {
  const maxSize = cleanUpper(locker.max_package_size || '');
  const capacityStatus = cleanUpper(locker.capacity_status || '');

  let eligible = true;
  let reason = 'Compatible';

  if ((sizeRank[maxSize] || 0) < (sizeRank[packageSize] || 0)) {
    eligible = false;
    reason = `Locker max ${maxSize} < package ${packageSize}`;
  } else if (capacityStatus === 'FULL') {
    eligible = false;
    reason = 'Locker is FULL';
  } else if (capacityStatus === 'LIMITED' && packageSize !== 'SMALL') {
    eligible = false;
    reason = 'Locker is LIMITED - only SMALL packages accepted';
  }

  return {
    ...locker,
    zip_code: cleanText(locker.zip_code || zipCode),
    max_package_size: maxSize || locker.max_package_size,
    capacity_status: capacityStatus || locker.capacity_status,
    eligible,
    reason,
    tool_name: 'Tool_locker_availability',
  };
}

const evaluatedLockers = lockers.map(evaluateLocker);
const eligibleLockers = evaluatedLockers.filter(locker => locker.eligible);

let availability_status = 'UNAVAILABLE';
let reason = 'No eligible locker is available for this package.';

if (lockers.length === 0) {
  availability_status = 'NO_LOCKERS_FOUND';
  reason = `No lockers found for zip code ${zipCode}.`;
} else if (eligibleLockers.length > 0) {
  availability_status = 'AVAILABLE';
  reason = 'Eligible locker is available.';
} else if (
  evaluatedLockers.some(
    locker => cleanUpper(locker.capacity_status || '') === 'FULL'
  )
) {
  availability_status = 'FULL';
  reason = 'Local locker is full or unavailable.';
}

return [
  {
    json: {
      tool_name: 'Tool_locker_availability',
      zip_code: zipCode,
      package_size: packageSize,
      availability_status,
      eligible: eligibleLockers.length > 0,
      reason,
      selected_locker: eligibleLockers[0] || null,
      lockers: evaluatedLockers,
    },
  },
];
